### ✅ **1. API Endpoint Design: Request/Response Schema**

**Endpoint**: `PUT /api/profile`  
**Auth Required**: Yes (`Authorization: Bearer <JWT>`)  
**Content-Type**: `application/json`

#### 🔹 Request Body (JSON)
```json
{
  "email": "user@example.com",
  "name": "John Doe",
  "phone": "+1234567890"
}
```

**Validation Rules**:
- `email`: required, valid email format (RFC 5322), max 256 chars.
- `name`: optional, trimmed string, max 100 chars.
- `phone`: optional, E.164 format (e.g., `+1234567890`), max 15 digits.

> 🛡️ **Sanitization**: Strip HTML/script tags; normalize whitespace.

#### 🔹 Response Schema

**Success (200 OK)**:
```json
{
  "status": "success",
  "message": "Profile updated successfully"
}
```

**Error Examples**:
- `400 Bad Request`:
  ```json
  { "status": "error", "message": "Invalid email format" }
  ```
- `401 Unauthorized`:
  ```json
  { "status": "error", "message": "Invalid or missing token" }
  ```
- `500 Internal Server Error`:
  ```json
  { "status": "error", "message": "Database update failed" }
  ```

---

### 🔐 **2. JWT Middleware Implementation** (`authMiddleware.js`)

```javascript
const jwt = require('jsonwebtoken');
const jwksClient = require('jwks-rsa');

const client = jwksClient({
  jwksUri: `https://auth.example.com/.well-known/jwks.json`
});

function getKey(header, callback) {
  client.getSigningKey(header.kid, (err, key) => {
    if (err) return callback(err);
    callback(null, key.getPublicKey());
  });
}

exports.authenticateJWT = (req, res, next) => {
  const authHeader = req.headers.authorization;
  const token = authHeader && authHeader.split(' ')[1]; // Bearer <token>

  if (!token) {
    console.log(`[${new Date().toISOString()}] AUTH-FAIL: No token provided`);
    return res.status(401).json({
      status: "error",
      message: "Invalid or missing token"
    });
  }

  jwt.verify(token, getKey, {
    issuer: 'https://auth.example.com',
    algorithms: ['RS256']
  }, (err, user) => {
    if (err) {
      console.log(`[${new Date().toISOString()}] AUTH-FAIL: JWT validation error - ${err.message}`);
      return res.status(401).json({
        status: "error",
        message: "Invalid or expired token"
      });
    }

    req.user = user; // Attach user identity (e.g., sub/user_id)
    next();
  });
};
```

> ✅ Complies with `[AUTH-OAUTH2-JWT-R22]`: Validates signature, issuer, expiration.

